  const craftItem = it => { const en = L.enchList(it).map(x => L.ENCH[x.id].name + ' ' + ROMAN9[x.t]).join(', ');
    return L.gearName(it) + (it.up ? ' +' + it.up : '') + ' (' + L.RARITY.find(r => r.id === it.rar).name + ', floor ' + it.ilvl + '): ' + (itemEffect(it) || 'no stats') + (en ? '; ' + en : ''); };
